={{
(() => {
  const body =
    $json.body && typeof $json.body === "object" && !Array.isArray($json.body)
      ? $json.body
      : {};

  const details = {};

  const checkText = (field, min, max) => {
    const value = body[field];

    if (typeof value !== "string") {
      details[field] = "Must be a string.";
      return;
    }

    const length = value.trim().length;

    if (length < min || length > max) {
      details[field] =
        "Must contain between " + min + " and " + max + " characters.";
    }
  };

  if (!["en", "es"].includes(body.locale)) {
    details.locale = 'Must be "en" or "es".';
  }

  checkText("fullName", 2, 80);

  checkText("email", 1, 254);
  if (
    typeof body.email === "string" &&
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())
  ) {
    details.email = "Must be a valid email address.";
  }

  if (
    typeof body.phone !== "string" ||
    !/^\+[1-9]\d{1,14}$/.test(body.phone)
  ) {
    details.phone = "Must be an E.164 phone number.";
  }

  checkText("company", 0, 120);

  if (!["automation", "consulting", "web_development", "other"].includes(body.service)) {
    details.service = "Contains an unsupported value.";
  }

  if (!["asap", "this_month", "exploring"].includes(body.timeline)) {
    details.timeline = "Contains an unsupported value.";
  }

  checkText("message", 10, 2000);

  if (body.consent !== true) {
    details.consent = "Must be true.";
  }

  const valid = Object.keys(details).length === 0;

  return {
    valid,
    validationError: valid ? null : "The lead payload contains invalid fields.",
    details,
  };
})()
}}

