        },
        manualReview: {
          type: 'boolean'
        },
        summary: {
          type: 'string',
          minLength: 10,
          maxLength: 280
        }
      },
      required: ['priority', 'manualReview', 'summary'],
      additionalProperties: false
    },
    messages: [
      {
        role: 'user',
        content: `Classify this inbound lead. Return only the requested JSON.

Rules:
- high: urgent and concrete project.
- normal: clear project without immediate urgency.
- low: a concrete project or desired outcome with low urgency.
- manualReview: true when the message does not state a clear task, desired outcome, or minimally actionable scope; also when data is ambiguous, contradictory, or insufficient.
- Write summary in the locale provided.
- Do not decide whether to contact, reject, book, or send a message.

Lead:
${JSON.stringify({
  locale: lead.locale,
  service: lead.service,
  timeline: lead.timeline,
  company: lead.company,
  message: lead.message
})}`
      }
    ]
  };
})()
}}

assignments.value:
={{
(() => {
  try {
    const value = JSON.parse($json.message?.content ?? '');
    const allowedPriorities = ['high', 'normal', 'low'];
    const allowedKeys = ['priority', 'manualReview', 'summary'];

    const valid =
      value &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      Object.keys(value).length === allowedKeys.length &&
      Object.keys(value).every((key) => allowedKeys.includes(key)) &&
      allowedPriorities.includes(value.priority) &&
      typeof value.manualReview === 'boolean' &&
      typeof value.summary === 'string' &&
      value.summary.trim().length >= 10 &&
      value.summary.trim().length <= 280;

    if (!valid) {
      return {
        valid: false,
        error: 'The model response does not match the classification schema.'
      };
    }

    return {
      valid: true,
      priority: value.priority,
      manualReview: value.manualReview,
      summary: value.summary.trim()
    };
  } catch {
    return {
      valid: false,
      error: 'The model response is not valid JSON.'
    };
  }
})()
}}

