    aiPriority: $json.classification.priority,
    priority: priorityByTimeline[timeline] ?? 'low'
  };
})()
}}

additionalFields.firstName:
={{
(() => {
  const fullName = $('Receive lead').first().json.body.fullName.trim();
  const parts = fullName.split(/\s+/);

  return parts.length > 1
    ? parts.slice(0, -1).join(' ')
    : fullName;
})()
}}
